1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, staleDispatchIssues, staleEscalationComment,
18	  rearmDispatchIssues, readyLabelOn, staleClaimedDispatchIssues, staleClaimComment,
19	  AGENT_RUNNING_LABEL,
20	} from './dispatch.mjs';
21	import { isAgentless } from './model-map.mjs';
22	import { localSignalContext } from './signals/local.mjs';
23	import { runPreprocessing, preprocessingFailure, agentRequestPath, clearAgentRequest, agentRequested } from './preprocess.mjs';
24	
25	// The due tasks, each paired with the slot it runs under. Union the discovered
26	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
27	// frequencies back to their tasks. A task whose frequency isn't due drops out.
28	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess) {
29	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
30	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
31	  const out = [];
32	  for (const task of tasks) {
33	    const slot = due.get(task.decl.frequency);
34	    if (slot) out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime });
35	  }
36	  return out;
37	}
38	
39	// The union of signal names the due tasks declare — the scheduler collects only
40	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
41	export function signalsUnion(dueTaskSlots) {
42	  const names = new Set();
43	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
44	  return [...names];
45	}
46	
47	// The signal-collection lookback: the widest due task's period plus 1h slack
48	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
49	const FREQUENCY_MS = {
50	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
51	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
52	};
53	export function windowStart(dueTaskSlots, now) {
54	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
55	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
56	}
57	
58	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
59	// precondition converges to a skip with the error recorded — it never sinks the
60	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
61	// issue separately.
62	export function runPrecondition(task, signals, packConfig) {
63	  try {
64	    const v = task.decl.precondition(signals, packConfig) ?? {};
65	    return {
66	      run: v.run === true,
67	      reason: v.reason ?? '',
68	      context: Array.isArray(v.context) ? v.context : [],
69	    };
70	  } catch (e) {
71	    return { run: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
72	  }
73	}
74	
75	// A human-readable job-summary line per evaluated task — the observability the
76	// old plan.json gave (DESIGN §3.6).
77	export function renderSummary(evaluations) {
78	  return evaluations.map((e) => {
79	    const verb = !e.run ? 'skip' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
80	    return `- ${e.pack}/${e.task} [${e.slotId}] ${verb} — ${e.reason || e.dispatch?.reason || ''}`.trimEnd();
81	  }).join('\n');
82	}
83	
84	// Orchestrate one scheduler run into a set of decisions — the reusable core the
85	// CLI wraps with real GitHub I/O. Injected seams:
86	//   collectSignals(names) -> signals object (the declared union, collected once)
87	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
88	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state}]
89	// Returns `{ evaluations }`: one record per due task with its precondition
90	// verdict and, when it runs, either an inline marker (agent_model: none) or a
91	// dispatch decision (planDispatch).
92	export async function planRun({
93	  tasks, schedule, now, lastSuccess,
94	  collectSignals, packConfigFor = () => ({}), existingIssuesFor = async () => [],
95	}) {
96	  const dueList = computeDueTaskSlots(tasks, schedule, now, lastSuccess);
97	  const signals = await collectSignals(signalsUnion(dueList));
98	
99	  const evaluations = [];
100	  for (const { task, slotId } of dueList) {
101	    const pre = runPrecondition(task, signals, packConfigFor(task.pack));
102	    const rec = {
103	      pack: task.pack, task: task.id, slotId,
104	      model: task.decl.agent_model, outcome: task.decl.expected_outcome,
105	      run: pre.run, reason: pre.reason, context: pre.context,
106	    };
107	    if (pre.error) rec.error = pre.error;
108	    if (pre.run) {
109	      // A declared agent_preprocessing runs as a subprocess BEFORE any agent
110	      // (DESIGN §3) — flagged here (pure) for the summary; the CLI shell executes
111	      // it. An agentless task is preprocessing-only; an agentful one hands off to
112	      // the agent after preprocessing succeeds.
113	      if (task.decl.agent_preprocessing) rec.preprocessing = true;
114	      if (isAgentless(task.decl.agent_model)) {
115	        // agent_model: none — no agent and no dispatch issue on success. A task with
116	        // no preprocessing runs the legacy inline worker; with preprocessing it is
117	        // the subprocess above.
